import { describe, expect, it, vi } from "vitest";
import { Orchestrator } from "../../src/lib/orchestrator.js";
import { AgentRouter } from "../../src/lib/agent-router.js";

/**
 * Regression coverage for the paid-decomposition pre-check gate
 * (Orchestrator.addTask -> this._router.assertDispatchAvailable?.()).
 *
 * The gate must run before any paid decomposition (`_decompose`) and before
 * any start notification (`notifier.notifyStart`). This suite verifies that
 * the rejected-backend paths terminate before those side effects, and that an
 * admitted (non-CLI) backend proceeds past the gate.
 */

function makeOrchestrator(backends) {
  const router = new AgentRouter({ agents: { backends } });
  const notifier = { isConfigured: true, notifyStart: vi.fn().mockResolvedValue({}) };
  const evolutionCompositionFactory = vi.fn();
  const orch = new Orchestrator({
    router,
    notifier,
    evolutionCompositionFactory,
  });
  return { orch, notifier, evolutionCompositionFactory };
}

// Non-CLI backend (e.g. an HTTP model backend) admits dispatch; `isCLI` is
// derived from the backend shape and defaults to false for such entries.
const NON_CLI_BACKEND = {
  type: "ollama",
  model: "qwen2.5-coder:7b",
  apiKey: "test-key",
};

const CLI_ONLY_BACKEND = { type: "claude", name: "external-cli" };

describe("paid decomposition pre-check", () => {
  it("admits dispatch and proceeds to decomposition for a non-CLI backend", async () => {
    const { orch, notifier, evolutionCompositionFactory } = makeOrchestrator([
      NON_CLI_BACKEND,
    ]);
    const decompose = vi
      .spyOn(orch, "_decompose")
      .mockResolvedValue([{ id: "sub-1", description: "fix" }]);

    await expect(
      orch.addTask("fix this bug", { source: "cli", cwd: process.cwd() }),
    ).resolves.toBeDefined();

    expect(decompose).toHaveBeenCalledTimes(1);
    expect(evolutionCompositionFactory).toHaveBeenCalledTimes(1);
    expect(notifier.notifyStart).toHaveBeenCalledTimes(1);
    expect(orch._tasks.size).toBe(1);
  });

  it("rejects CLI-only backends before decomposition and notification", async () => {
    const { orch, notifier, evolutionCompositionFactory } = makeOrchestrator([
      CLI_ONLY_BACKEND,
    ]);
    const decompose = vi.spyOn(orch, "_decompose").mockResolvedValue([]);

    const promise = orch.addTask("fix this bug", {
      source: "cli",
      cwd: process.cwd(),
    });

    await expect(promise).rejects.toMatchObject({
      code: "AGENT_ROUTER_EXTERNAL_MODEL_INGRESS_UNATTESTED",
    });

    expect(decompose).not.toHaveBeenCalled();
    expect(evolutionCompositionFactory).not.toHaveBeenCalled();
    expect(notifier.notifyStart).not.toHaveBeenCalled();
    expect(orch._tasks.size).toBe(0);
  });

  it("rejects empty backends with AGENT_ROUTER_NO_BACKENDS before decomposition and notification", async () => {
    const { orch, notifier, evolutionCompositionFactory } = makeOrchestrator([]);
    const decompose = vi.spyOn(orch, "_decompose").mockResolvedValue([]);

    const promise = orch.addTask("fix this bug", {
      source: "cli",
      cwd: process.cwd(),
    });

    await expect(promise).rejects.toMatchObject({
      code: "AGENT_ROUTER_NO_BACKENDS",
    });

    expect(decompose).not.toHaveBeenCalled();
    expect(evolutionCompositionFactory).not.toHaveBeenCalled();
    expect(notifier.notifyStart).not.toHaveBeenCalled();
    expect(orch._tasks.size).toBe(0);
  });
});

