  ])(
    "stops before execution when decomposition fails terminally: %j",
    async (fields) => {
      const { orch } = buildOrchestrator();
      orch._chat = vi.fn().mockRejectedValue(
        new Error("wrapped denial", {
          cause: Object.assign(new Error("denied"), fields),
