    orch.on("task:decomposed", decomposedFn);

    await orch.addTask("task", { cwd: "/tmp" });
    expect(decomposedFn).toHaveBeenCalledTimes(1);
    expect(decomposedFn.mock.calls[0][0].subtasks).toHaveLength(1);
  });
});

