import { createTestEvolutionCompositionFactory } from "../helpers/test-model-egress.js";
import runtimeClaimsContract from "@chainlesschain/session-core/runtime-claims";
/**
 * Integration tests: Orchestrator full pipeline
 *
 * Tests the complete flow:
 *   addTask → LLM decompose → AgentRouter dispatch → CI check → notify
 *
 * External dependencies (LLM, CI, spawn) are mocked; all internal
 * orchestration logic runs for real.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import {
  Orchestrator,
  TASK_STATUS,
  TASK_SOURCE,
} from "../../src/lib/orchestrator.js";
import { _deps as bridgeDeps } from "../../src/lib/claude-code-bridge.js";
import { _deps as orchDeps } from "../../src/lib/orchestrator.js";

// ─── Helpers ─────────────────────────────────────────────────────

function makeChildProcess(stdout = "", exitCode = 0) {
  const { EventEmitter } = require("events");
  const proc = new EventEmitter();
  proc.stdout = new EventEmitter();
  proc.stderr = new EventEmitter();
  proc.kill = vi.fn();
  process.nextTick(() => {
    if (stdout) proc.stdout.emit("data", Buffer.from(stdout));
    proc.emit("close", exitCode);
  });
  return proc;
}

const AGENT_SUCCESS_OUTPUT =
  JSON.stringify({ type: "result", result: "Fixed!" }) + "\n";
const { RUNTIME_MODE, TERMINAL_EVIDENCE_KIND, createRuntimeClaims } =
  runtimeClaimsContract;
const TEST_AGENT_RUNTIME_CLAIMS = createRuntimeClaims({
  mode: RUNTIME_MODE.REAL_EXECUTION,
});
const TEST_AGENT_TERMINAL_EVIDENCE = Object.freeze([
  Object.freeze({
    kind: TERMINAL_EVIDENCE_KIND.RUNTIME_EVENT,
    outcome: "completed",
    source: "orchestrator-test-router",
  }),
  Object.freeze({
    kind: TERMINAL_EVIDENCE_KIND.TEST_RECEIPT,
    digest: `sha256:${"a".repeat(64)}`,
  }),
]);

/**
 * Keep the integration fake behind the same task-scoped evolution authority
 * used by production. The call wrapper replaces only the external provider;
 * createChatFn still captures the authenticated ingress before invoking it.
 */
function configureTestModelEgress(orch) {
  orch._evolutionCompositionFactory = createTestEvolutionCompositionFactory();
  orch._llmOptions = {
    ...orch._llmOptions,
    provider: "ollama",
    callWrapper: async () => ({ content: await orch._chat() }),
  };
  orch._router.dispatch = vi.fn(async (subtasks, { cwd }) =>
    subtasks.map((subtask, index) => {
      const prompt = subtask.context
        ? `${subtask.description}\n\n${subtask.context}`
        : subtask.description;
      bridgeDeps.spawn("claude", ["-p", prompt], { cwd });
      return {
        taskId: subtask.id,
        agentId: `test-agent-${index}`,
        backendType: "test",
        success: true,
        status: "completed",
        output: "Fixed!",
        exitCode: 0,
        duration: 0,
        runtimeClaims: TEST_AGENT_RUNTIME_CLAIMS,
        terminalEvidence: TEST_AGENT_TERMINAL_EVIDENCE,
      };
    }),
  );
  return orch;
}

/** Build an Orchestrator with LLM + CI + spawn all mocked. */
function buildOrchestrator({
  decomposeTo = [{ id: "sub-1", description: "fix" }],
  agentExitCode = 0,
  ciPasses = true,
  notifySend = vi.fn(),
} = {}) {
  // Mock spawn for claude CLI
  bridgeDeps.spawn = vi.fn(() =>
    makeChildProcess(
      agentExitCode === 0 ? AGENT_SUCCESS_OUTPUT : "",
      agentExitCode,
    ),
  );
  bridgeDeps.execSync = vi.fn((cmd) => {
    if (cmd.includes("--version")) return "2.0.0";
    throw new Error("not found");
  });

  // Mock CI command
  orchDeps.execSync = vi.fn((cmd) => {
    if (!ciPasses) {
      const err = new Error("CI failed");
      err.stdout = "FAIL src/app.test.js\n  ✕ should work\n";
      err.stderr = "Error: expected true";
      throw err;
    }
    return "All tests passed";
  });

  const orch = configureTestModelEgress(
    new Orchestrator({
      cwd: "/tmp/test-project",
      maxParallel: 2,
      maxRetries: 1,
      ciCommand: "npm test",
      verbose: false,
    }),
  );

  // Mock LLM chat for decomposition
  orch._chat = vi.fn(async () => JSON.stringify(decomposeTo));

  // Add a mock notification channel
  const notifier = {
    isConfigured: true,
    notifyStart: vi.fn(() => Promise.resolve({ ok: true })),
    notifySuccess: vi.fn(() => Promise.resolve({ ok: true })),
    notifyFailure: vi.fn(() => Promise.resolve({ ok: true })),
  };
  orch.notifier.add("mock", notifier);

  return { orch, notifier };
}

// ─── Basic task lifecycle ─────────────────────────────────────────

describe("Orchestrator: task lifecycle", () => {
  it("rejects CLI-only routing before model work, notifications and Run creation", async () => {
    const composition = vi.fn();
    const notifyStart = vi.fn();
    const orch = new Orchestrator({
      agents: { backends: [{ type: "claude" }, { type: "codex" }] },
      notifier: { isConfigured: true, notifyStart },
      evolutionCompositionFactory: composition,
    });
    const decompose = vi.spyOn(orch, "_decompose");
    await expect(orch.addTask("fix this")).rejects.toMatchObject({
      code: "AGENT_ROUTER_EXTERNAL_MODEL_INGRESS_UNATTESTED",
    });
    expect(decompose).not.toHaveBeenCalled();
    expect(composition).not.toHaveBeenCalled();
    expect(notifyStart).not.toHaveBeenCalled();
    expect(orch._tasks.size).toBe(0);
  });
  let originalBridgeDeps;
  let originalOrchDeps;

  beforeEach(() => {
    originalBridgeDeps = { ...bridgeDeps };
    originalOrchDeps = { ...orchDeps };
  });

  afterEach(() => {
    Object.assign(bridgeDeps, originalBridgeDeps);
    Object.assign(orchDeps, originalOrchDeps);
    vi.clearAllMocks();
  });

  it("completes a task with CI pass → status COMPLETED", async () => {
    const { orch } = buildOrchestrator({ ciPasses: true });
    const task = await orch.addTask("Fix auth bug", {
      source: TASK_SOURCE.CLI,
      cwd: "/tmp",
    });

    expect(task.status).toBe(TASK_STATUS.COMPLETED);
    expect(task.subtasks).toHaveLength(1);
    expect(task.agentResults).toHaveLength(1);
    expect(task.agentResults[0].success).toBe(true);
    expect(task.retries).toBe(0);
  });

  it("emits task:complete event on success", async () => {
    const { orch } = buildOrchestrator({ ciPasses: true });
    const completeFn = vi.fn();
    orch.on("task:complete", completeFn);

    await orch.addTask("task", { cwd: "/tmp" });
    expect(completeFn).toHaveBeenCalledTimes(1);
    expect(completeFn.mock.calls[0][0].status).toBe(TASK_STATUS.COMPLETED);
  });

  it.each(["factory-error", "unbranded"])(
    "records failed admission before dispatch: %s",
    async (mode) => {
      const { orch, notifier } = buildOrchestrator();
      orch._evolutionCompositionFactory = async () => {
        if (mode === "factory-error") throw new Error("authority unavailable");
        return {};
      };
      const failed = vi.fn();
      orch.on("task:failed", failed);
      await expect(orch.addTask("task")).rejects.toThrow();
      expect(orch.status().tasks[0].status).toBe(TASK_STATUS.FAILED);
      expect(failed).toHaveBeenCalledTimes(1);
      expect(orch._chat).not.toHaveBeenCalled();
      expect(bridgeDeps.spawn).not.toHaveBeenCalled();
      expect(orchDeps.execSync).not.toHaveBeenCalled();
      expect(notifier.notifySuccess).not.toHaveBeenCalled();
    },
  );

  it.each([true, false])(
    "waits for evolution settlement before success (CI=%s)",
    async (runCI) => {
      const { orch, notifier } = buildOrchestrator();
      let settle;
      let entered;
      const started = new Promise((resolve) => {
        entered = resolve;
      });
      const settlement = new Promise((resolve) => {
        settle = resolve;
      });
      const ingress = {
        complete: vi.fn(() => {
          entered();
          return settlement;
        }),
      };
      // Isolate completion ordering from the separately tested projection transport.
      const completeTask = orch._completeTask.bind(orch);
      orch._completeTask = (task, _evolutionIngress, ciResult) =>
        completeTask(task, ingress, ciResult);
      const completed = vi.fn();
      orch.on("task:complete", completed);
      const pending = orch.addTask("task", { runCI });
      await started;
      expect(orch.status().tasks[0].status).toBe(TASK_STATUS.FINALIZING);
      expect(completed).not.toHaveBeenCalled();
      expect(notifier.notifySuccess).not.toHaveBeenCalled();
      settle();
      const task = await pending;
      expect(task.status).toBe(TASK_STATUS.COMPLETED);
      expect(ingress.complete).toHaveBeenCalledTimes(1);
      expect(completed).toHaveBeenCalledTimes(1);
      expect(notifier.notifySuccess).toHaveBeenCalledTimes(runCI ? 1 : 0);
    },
  );

  it.each([true, false])(
    "does not announce success when evolution settlement fails (CI=%s)",
    async (runCI) => {
      const { orch, notifier } = buildOrchestrator();
      const ingress = {
        complete: vi.fn().mockRejectedValue(new Error("witness unavailable")),
      };
      const completeTask = orch._completeTask.bind(orch);
      orch._completeTask = (task, _evolutionIngress, ciResult) =>
        completeTask(task, ingress, ciResult);
      const completed = vi.fn();
      const failed = vi.fn();
      orch.on("task:complete", completed);
      orch.on("task:failed", failed);
      const task = await orch.addTask("task", { runCI });
      expect(task.status).toBe(TASK_STATUS.FAILED);
      expect(task.completedAt).toBeNull();
      expect(completed).not.toHaveBeenCalled();
      expect(notifier.notifySuccess).not.toHaveBeenCalled();
      expect(failed).toHaveBeenCalledTimes(1);
    },
  );

  it("calls notifyStart and notifySuccess on successful pipeline", async () => {
    const { orch, notifier } = buildOrchestrator({ ciPasses: true });
    await orch.addTask("task", { cwd: "/tmp", notify: true });

    expect(notifier.notifyStart).toHaveBeenCalledTimes(1);
    expect(notifier.notifySuccess).toHaveBeenCalledTimes(1);
    expect(notifier.notifyFailure).not.toHaveBeenCalled();
  });

  it("skips CI when runCI=false", async () => {
    const { orch } = buildOrchestrator({ ciPasses: true });
    const task = await orch.addTask("task", { cwd: "/tmp", runCI: false });

    expect(task.status).toBe(TASK_STATUS.COMPLETED);
    expect(orchDeps.execSync).not.toHaveBeenCalled();
  });

  it("records completedAt timestamp on success", async () => {
    const { orch } = buildOrchestrator({ ciPasses: true });
    const task = await orch.addTask("task", { cwd: "/tmp" });
    expect(task.completedAt).toBeDefined();
    expect(new Date(task.completedAt).getTime()).toBeLessThanOrEqual(
      Date.now(),
    );
  });
});

